    id: "158", name:"Max Planck", category:"science", headline:"The Dawn of Quantum Physics", shortDescription:"Max Planck was the pioneer of the quantum revolution that reshaped 20th-century physics. His groundbreaking discoveries laid the foundation for modern science.", slug:"max-planck", dnaCode:"LPDI", quote:"A new scientific truth does not triumph by convincing its opponents and making them see the light, but rather because its opponents eventually die, and a new generation grows up that is familiar with it.", pain:"He endured immense personal tragedy, losing his wife and two sons. He also lived through the devastating impacts of two World Wars and the rise of the Nazi regime, which created a challenging environment for science.", recovery:"Planck's unwavering dedication to science and his belief in reason and humanity helped him navigate these profound losses and societal upheavals. He actively worked to rebuild scientific institutions and foster international collaboration after the wars.",
