    id: "162", name:"Dmitri Mendeleev", category:"science", headline:"Architect of the Periodic Table", shortDescription:"A Russian chemist and physicist, he is best known for formulating the Periodic Law and creating a definitive version of the periodic table of elements. His work laid a foundational stone for modern chemistry.", slug:"dmitri-mendeleev", dnaCode:"LPDI", quote:"I concluded that the properties of elements depend on their atomic weights.", pain:"He faced significant financial hardship following his father's early death and the limitations of scientific research within Tsarist Russia. His groundbreaking periodic table also met considerable skepticism and opposition from the scientific community initially.", recovery:"With the support of his family and his own tenacious dedication, he persevered through his studies. Mendeleev's breakthrough came from recognizing a clear periodicity in the properties of elements based on their atomic weights, which led him to not only organize them but also predict the existence and properties of undiscovered elements. Over time, his predictions were experimentally verified, earning him widespread acclaim.",
    lessons: [],
    persona: "당신은 드미트리 멘델레예프이다.", imageUrl:"/images/giants/dmitri-mendeleev.jpg", era:"19th Century"
