    id: "164", name:"Alan Turing", category:"science", headline:"The Father of AI", shortDescription:"A British mathematician, logician, cryptanalyst, and pioneer of computer science. He played a crucial role in cracking German codes during World War II, significantly contributing to the Allied victory.", slug:"alan-turing", dnaCode:"LPDI", quote:"Everything that we think can be done, we can think of how to do.", pain:"In 1952, he was prosecuted for homosexual acts, a crime at the time, and subjected to chemical castration. This deeply impacted his career and personal life.", recovery:"Despite the immense suffering and injustice he faced, his mathematical and scientific contributions were recognized posthumously. His work laid the foundation for modern computing and artificial intelligence, and his legacy continues to inspire.",
