    id: "169", name:"Gregor Mendel", category:"science", headline:"Discoverer of Heredity Laws", shortDescription:"An Austrian monk and botanist of the 19th century, he discovered the fundamental laws of inheritance through his experiments with pea plants. His work laid the foundation for modern genetics.", slug:"gregor-mendel", dnaCode:"LPDI", quote:"It is my only happiness to dedicate the purpose of my life to my scientific work.", pain:"Mendel experienced the frustration of his groundbreaking genetic research being largely ignored and forgotten during his lifetime. Furthermore, the lack of peer scientists to support his academic passion and the challenge to the prevailing scientific paradigms of the time led to profound isolation.", recovery:"Mendel found satisfaction in the pursuit of truth itself, rather than seeking external recognition. He diligently fulfilled his duties as abbot while continuously pursuing his research. His firm conviction and persistent efforts ultimately became the driving force for his achievements to be re-evaluated by later generations.",
