    id: "175", name:"Rumi", category:"science", headline:"Poet of Divine Love", shortDescription:"Jalāl al-Dīn Muḥammad Rūmī was a 13th-century Persian poet, Islamic scholar, theologian, and Sufi mystic. His profound poetry, often exploring themes of divine love and the unity of existence, continues to resonate globally.", slug:"rumi", dnaCode:"LPDI", quote:"What you seek is seeking you.", pain:"Rumi experienced profound grief with the death of his father and the displacement caused by the Mongol invasions, forcing him to leave his homeland and live as a refugee.", recovery:"His encounter with Shams al-Din Tabrizi, a wandering dervish, was a pivotal moment. Shams's spiritual presence and teachings ignited Rumi's poetic genius, transforming his grief into ecstatic verse and leading him to establish the Mevlevi Order.",
