    id: "176", name:"Ibn Rushd", category:"science", headline:"The Commentator", shortDescription:"Ibn Rushd was a towering figure of the 12th-century Islamic world, renowned as a philosopher, jurist, and physician. He is celebrated for his commentaries on Aristotle, which significantly influenced both Islamic and European thought.", slug:"ibn-rushd", dnaCode:"LPDI", quote:"Action is the result of will, and will is the result of knowledge.", pain:"He faced persecution from conservative religious authorities and political factions who condemned his philosophical pursuits as heretical, leading to his works being banned and his exile.", recovery:"He meticulously preserved his writings and ideas privately, and through his dedicated students, ensured the continuation of his rationalist inquiries, thereby safeguarding his intellectual legacy.",
