    id: "177", name:"William James", category:"science", headline:"The Stream of Consciousness", shortDescription:"An American philosopher and psychologist, he was one of the founders of pragmatism. His monumental work, 'The Principles of Psychology,' laid the groundwork for modern psychology.", slug:"william-james", dnaCode:"LPDI", quote:"The art of being wise is the art of knowing what to overlook.", pain:"Suffered from severe neurasthenia and bouts of depression from his youth, which significantly hampered his studies and daily life. He also grappled with his father's demanding educational approach and profound existential doubts about his own path.", recovery:"Through intense psychological distress, he began to philosophically examine his own experiences. He cultivated self-awareness and believed in the power of will, striving to overcome his struggles through 'the will to believe.' This became a cornerstone of his pragmatic philosophy.",
