    id: "179", name:"George Washington Carver", category:"science", headline:"The Peanut Wizard", shortDescription:"Born into slavery, he rose to become a brilliant agricultural scientist and inventor. He developed over 300 uses for peanuts, sweet potatoes, and soybeans, revolutionizing the Southern agricultural economy.", slug:"george-washington-carver", dnaCode:"LPDI", quote:"How far you go in life depends on you being tender with the young, compassionate with the aged, sympathetic with the struggling and tolerant of the weak and the strong. Because someday in your life, you will have been all of these.", pain:"Born into slavery, he faced immense hardship before gaining freedom. He also encountered racial discrimination, limiting his educational and research opportunities.", recovery:"Through his exceptional intellect and relentless dedication, he overcame these adversities. His groundbreaking research in agricultural science proved his capabilities and inspired countless individuals.",
