      {
        "title": "생물은 고립된 부분의 집합이 아니라, 상호 작용하는 체계이다.", "content": "생명체의 모든 신체 부위는 서로 긴밀히 의존하며 하나의 완전한 기능을 이룬다는 통찰을 담고 있다."
      },
      {
        "title": "화석은 지구의 과거 역사를 읽을 수 있는 가장 확실한 메달이다.", "content": "화석이 단순한 돌덩이가 아니라, 과거 시대의 진실을 증명하는 결정적 증거임을 뜻한다."
      }
