        "title": "가장 오래되고 짧은 두 단어, '예'와 '아니오'는 가장 많은 생각을 필요로 하는 단어이다.", "content": "결정을 내리고 자신의 의사를 명확히 밝히는 일에는 막중한 책임이 따르므로, 신중한 숙고가 선행되어야 함을 일깨웁니다."
