        "title": "모든 인류가 한 사람의 의견에 반대하더라도, 그 한 사람을 침묵시킬 권리는 없다.", "content": "사상의 자유와 표현의 자유가 사회 전체의 다수결이나 편견에 의해 억압받아서는 안 된다는 것을 강조한다."
