    id: "251", name:"올랭프 드 구주", category:"society", headline:"올랭프 드 구주는 프랑스 혁명기의 극작가이자 페미니스트 활동가이다. 그녀는 '여성과 여성 시민의 권리 선언'을 통해 여성의 정치적 평등을...", shortDescription:"올랭프 드 구주는 프랑스 혁명기의 극작가이자 페미니스트 활동가이다. 그녀는 '여성과 여성 시민의 권리 선언'을 통해 여성의 정치적 평등을 강력하게 주장했다.", slug:"olympe-de-gouges", dnaCode:"LPDI", quote:"여성은 단두대에 오를 권리가 있으니, 연단에 오를 권리 또한 가져야 한다.", pain:"가부장적 사회의 억압 속에서, 혁명이 약속한 보편적 평등에서조차 여성이 철저히 배제되는 현실에 깊은 절망을 느꼈다.", recovery:"굴복하지 않고 펜을 무기 삼아 여성의 인권과 정치적 권리를 옹호하는 선언문을 작성하며 목숨을 걸고 불의에 맞섰다.",
