    id: "284", name:"윌리엄 틴들", category:"philosophy", headline:"성경을 백성에게", shortDescription:"16세기 초 영국의 신학자이자 번역가로, 최초로 영어 성경을 대중에게 보급하는 데 헌신했다. 그의 번역은 현대 영어 성경의 기반이 되었다.", slug:"william-tyndale", dnaCode:"PPHI", quote:"“하나님이 사람을 만드신 것이 아니라, 사람이 하나님을 만들었다.”", pain:"당시 교회와 권력층은 라틴어로 된 성서만을 고집하며 일반 대중이 성서를 읽는 것을 금지했다. 틴들은 이러한 억압 속에서 비밀리에, 그리고 위험을 무릅쓰고 성서 번역을 진행해야 했다. 그는 이단으로 몰려 수많은 추격과 박해를 받았으며, 결국 외국 땅에서 체포되어 억울한 죽음을 맞이했다.", recovery:"틴들은 자신의 번역본을 인쇄하여 몰래 영국으로 반입하고 배포하는 방식으로 대중에게 성서를 보급했다. 그의 헌신적인 노력은 비록 순교로 끝났지만, 그의 번역본은 영국 교회와 사회 전반에 지대한 영향을 미쳤으며, 결국 영어 성경의 표준이 되었다.",
